"use client";

import { useEffect, useMemo, useRef, useState, type FormEvent } from "react";
import Link from "next/link";
import { songCoverPath } from "@/lib/songCover";
import { CalendarDays, Camera, CheckCircle2, Clapperboard, Ellipsis, ArrowUp, ArrowDown, Copy, ExternalLink as ExternalLinkIcon, Film, GripVertical, Images, ImagePlus, LayoutGrid, Lightbulb, List, ListChecks, MapPin, Package, PanelsTopLeft, Plus, Rocket, Shirt, Trash2, Users, Clock3, Info, X } from "lucide-react";

type Project = { id: string; visibility: string; status: string; public_concept: string; public_status: string; next_action: string; workspace: Record<string, any>; assigned_videographer?: Record<string, any>; songs?: { title: string; slug: string } };
type Stage = "creative" | "production" | "release";
type Row = Record<string, any>;
const stages: Array<[Stage, string, string, typeof Lightbulb, string]> = [["creative", "Creative", "Vision & Storyboard", Lightbulb, "text-[#FD52AF]"], ["production", "Production", "Plan the Shoot", Clapperboard, "text-sky-300"], ["release", "Release", "Finish & Publish", Rocket, "text-violet-300"]];
const makeId = () => typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
const panel = "rounded-2xl border border-white/[.08] bg-[#111116]";
const field = "w-full rounded-lg border border-white/10 bg-black/25 px-3 py-2.5 text-sm text-white outline-none placeholder:text-white/30 focus:border-[#FD52AF]/60";

function cleanConcept(value: Row, index: number): Row {
  const scenes = Array.isArray(value.scenes) ? value.scenes.map((scene: Row, i: number) => ({ ...scene, id: scene.id || makeId(), number: i + 1, description: scene.description || scene.synopsis || "", referenceUrl: scene.referenceUrl || scene.reference_url || "", status: scene.status || "planned", characters: Array.isArray(scene.characters) ? scene.characters : [], shots: Array.isArray(scene.shots) ? scene.shots : [] })) : [];
  const title = /^Concept \d+$/i.test(String(value.title || "").trim()) ? "" : value.title || "";
  return { ...value, id: value.id || makeId(), title, synopsis: value.synopsis || value.story || "", styles: Array.isArray(value.styles) ? value.styles : [], scenes };
}
function sceneReferences(scene: Row): Row[] { const refs = Array.isArray(scene.referenceImages) ? scene.referenceImages : scene.referenceUrl ? [{ id: "legacy-cover", url: scene.referenceUrl }] : []; return refs.map((item: any, index: number) => typeof item === "string" ? { id: `reference-${index}`, url: item } : { ...item, id: item.id || `reference-${index}`, url: item.url || item.referenceUrl || "" }).filter((item: Row) => item.url); }
function sceneCover(scene: Row): string { const refs = sceneReferences(scene); return refs.find(row => row.id === scene.coverReferenceId)?.url || refs[0]?.url || scene.referenceUrl || ""; }
function initials(name: string) { return name.trim().split(/\s+/).slice(0, 2).map(word => word[0]).join("").toUpperCase() || "?"; }
function ChipGroup({ title, tip, values, selected, onToggle, onCustom }: { title: string; tip: string; values: string[]; selected: string[]; onToggle: (value: string) => void; onCustom: (value: string) => void }) {
  const [customOpen, setCustomOpen] = useState(false);
  const [customValue, setCustomValue] = useState("");
  function addCustom(event: FormEvent) { event.preventDefault(); const value = customValue.trim(); if (value && !values.some(item => item.toLowerCase() === value.toLowerCase())) onCustom(value); setCustomValue(""); setCustomOpen(false); }
  return <div><h3 className="mb-2 flex items-center gap-1.5 text-[.68rem] font-semibold text-white/60">{title}<span title={tip} className="text-white/35"><Info size={13}/></span></h3><div className="flex flex-wrap gap-1.5">{values.map(value => <button key={value} type="button" aria-pressed={selected.includes(value)} onClick={() => onToggle(value)} className={`rounded-full border px-2.5 py-1.5 text-xs transition ${selected.includes(value) ? "border-[#FD52AF]/50 bg-[#FD52AF]/10 text-[#ffadd6]" : "border-white/10 text-white/50 hover:border-white/20 hover:text-white/75"}`}>{value}</button>)}<button type="button" onClick={() => setCustomOpen(!customOpen)} aria-expanded={customOpen} className="rounded-full border border-dashed border-white/15 px-2.5 py-1.5 text-xs text-white/45 hover:border-[#FD52AF]/40">Custom <Plus size={12} className="inline"/></button></div>{customOpen && <form onSubmit={addCustom} className="mt-2 flex gap-2"><input autoFocus value={customValue} onChange={event => setCustomValue(event.target.value)} aria-label={`Custom ${title.toLowerCase()}`} placeholder={`Add ${title.toLowerCase()}`} className="w-48 rounded-lg border border-white/10 bg-black/25 px-3 py-2 text-xs text-white outline-none focus:border-[#FD52AF]/50"/><button type="submit" disabled={!customValue.trim()} className="rounded-lg bg-[#FD52AF] px-3 text-xs font-semibold text-black disabled:opacity-40">Add</button></form>}</div>;
}

export default function MusicVideoWorkspace({ id, embedded = false }: { id: string; embedded?: boolean }) {
  const [project, setProject] = useState<Project | null>(null);
  const [stage, setStage] = useState<Stage>("creative");
  const [notice, setNotice] = useState("Loading project…");
  const [activeScene, setActiveScene] = useState<string | null>(null);
  const [draftScene, setDraftScene] = useState<Row | null>(null);
  const [itemModal, setItemModal] = useState<{ type: string; index: number | null; value: Row } | null>(null);
  const [versionsOpen, setVersionsOpen] = useState(false);
  const [menuScene, setMenuScene] = useState<string | null>(null);
  const [dragOverScene, setDragOverScene] = useState<string | null>(null);
  const [sceneView, setSceneView] = useState<"grid" | "list">("grid");
  const [invites, setInvites] = useState<Record<string, { id: string; email: string; link?: string }>>({});
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const dragScene = useRef<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const response = await fetch(`/api/music-video-projects?id=${id}`, { cache: "no-store" });
        const result = await response.json();
        if (!response.ok) throw new Error(result.error || "Unable to load project.");
        const data = result.project as Project;
        const workspace = data.workspace || {};
        const oldConcepts = Array.isArray(workspace.creative?.concepts) ? workspace.creative.concepts : [];
        const title = String(data.songs?.title || "").toUpperCase();
        if (!oldConcepts.length && title.includes("AM I PRETTY WHEN I CRY")) {
          const legacy = await import("@/lib/musicVideoStarterConcepts").catch(() => null);
          if (legacy?.defaultConcepts) {
            workspace.creative = { ...(workspace.creative || {}), concepts: legacy.defaultConcepts(), selectedConceptId: "butterfly-switch" };
            await fetch("/api/music-video-projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: data.id, workspace }) });
          }
        }
        const inviteResponse = await fetch(`/api/music-video-invites?projectId=${encodeURIComponent(id)}`, { cache: "no-store" }).catch(() => null);
        if (inviteResponse?.ok) {
          const inviteData = await inviteResponse.json();
          if (!cancelled) setInvites(Object.fromEntries((inviteData.invites || []).map((invite: { id: string; email: string; expiresAt: string }) => [invite.email.toLowerCase(), { id: invite.id, email: invite.email }])));
        }
        if (!cancelled) { setProject({ ...data, workspace }); setNotice(""); }
      } catch (error) { if (!cancelled) setNotice(error instanceof Error ? error.message : "Unable to load project."); }
    })();
    return () => { cancelled = true; if (saveTimer.current) clearTimeout(saveTimer.current); };
  }, [id]);

  const workspace = project?.workspace || {};
  const creative = workspace.creative || {};
  const production = workspace.production || {};
  const release = workspace.release || {};
  const concepts: Row[] = useMemo(() => {
    const rows = Array.isArray(creative.concepts) ? creative.concepts : [];
    if (rows.length) return rows.map(cleanConcept);
    const legacyStory = creative.story || creative.overallConcept || "";
    const legacyScenes = Array.isArray(creative.scenes) ? creative.scenes : [];
    if (legacyStory || creative.aesthetic || creative.directorNotes || creative.visualReferences || legacyScenes.length) return [cleanConcept({ id: "legacy-main", title: creative.title || "Main concept", synopsis: legacyStory, styles: creative.styles || [], theme: creative.theme || creative.themes || "", aesthetic: creative.aesthetic || "", scenes: legacyScenes, decision: creative.decision || "", notes: creative.directorNotes || "", references: creative.visualReferences || "", shotList: creative.shotList || [] }, 0)];
    return [];
  }, [creative]);
  const selectedId = creative.selectedConceptId || concepts.find(row => !row.archived)?.id || concepts[0]?.id;
  const concept = concepts.find(row => row.id === selectedId) || concepts[0] || cleanConcept({ id: "new-concept", title: "", synopsis: "", styles: [], scenes: [] }, 0);
  const scenes: Row[] = concept.scenes || [];
  const people = workspace.people || {};
  const castStored: Row[] = Array.isArray(people.actors) ? people.actors : [];
  const cast: Row[] = [...castStored.filter((person: Row) => !person.archived)];
  if (project?.assigned_videographer?.name && !cast.some(person => person.email === project.assigned_videographer?.email || person.name === project.assigned_videographer?.name)) cast.push({ ...project.assigned_videographer, id: "assigned-videographer", role: "Videographer", status: "Invited" });
  const locations: Row[] = Array.isArray(people.locations) ? people.locations.filter((row: Row) => !row.archived) : [];
  const outfits: Row[] = Array.isArray(people.outfits) ? people.outfits.filter((row: Row) => !row.archived) : [];
  const props: Row[] = Array.isArray(people.props) ? people.props.filter((row: Row) => !row.archived) : [];
  const tasks: Row[] = Array.isArray(production.tasks) ? production.tasks : [];
  const active = scenes.find(scene => scene.id === activeScene) || (draftScene?.id === activeScene ? draftScene : null);
  const releasePublished = release.publicationConfirmed === true || release.publicationStatus === "Published";
  const editingStatus = ["Approved", "Complete"].includes(release.editingStatus) ? "Final" : ["In Review", "Ready for review"].includes(release.editingStatus) ? "In Review" : ["Editing", "In progress"].includes(release.editingStatus) ? "Editing" : "Not Started";
  const overall = releasePublished ? "Published" : editingStatus === "Final" && release.finalApproved === "yes" ? "Ready to publish" : editingStatus !== "Not Started" ? editingStatus : scenes.length && scenes.every(scene => scene.status === "filmed") ? "Filming complete" : scenes.length ? "In production" : "Concept";
  const visibleTasks = tasks.map((task: Row, index: number) => ({ task, index })).filter(({ task }) => String(task.name || "").trim());
  const doneTasks = visibleTasks.filter(({ task }) => task.status === "Done").length;
  const sortedTasks = [...visibleTasks].sort((a, b) => Number(a.task.status === "Done") - Number(b.task.status === "Done"));
  const stageProgress = {
    creative: Boolean(concept.synopsis?.trim()) || scenes.length > 0,
    production: Boolean(production.shootDate) || doneTasks > 0 || scenes.some(scene => scene.status === "filmed"),
    release: releasePublished || (editingStatus === "Final" && release.finalApproved === "yes"),
  };
  const savedLocationNames = locations.filter((row: Row) => row.name && !row.archived).map((row: Row) => row.name);
  const savedCastNames = cast.filter((row: Row) => row.name && !row.archived).map((row: Row) => row.name);

  function queueSave(nextWorkspace: Row) {
    if (!project) return;
    setProject(current => current ? { ...current, workspace: nextWorkspace } : current);
    setNotice("Saving…");
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      try {
        const nextRelease = nextWorkspace.release || {};
        const nextScenes = (nextWorkspace.creative?.concepts || []).find((row: Row) => row.id === nextWorkspace.creative?.selectedConceptId)?.scenes || [];
        const status = nextRelease.publicationConfirmed === true || nextRelease.publicationStatus === "Published" ? "complete" : nextRelease.editingStatus && nextRelease.editingStatus !== "Not Started" ? "editing" : nextScenes.length && nextScenes.every((scene: Row) => scene.status === "filmed") ? "filming" : nextScenes.length ? "planning" : "concept";
        const response = await fetch("/api/music-video-projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: project.id, workspace: nextWorkspace, status }) });
        const result = await response.json();
        if (!response.ok) throw new Error(result.error || "Save failed.");
        setNotice("Saved");
      } catch (error) { setNotice(error instanceof Error ? error.message : "Save failed."); }
    }, 450);
  }
  function update(section: string, value: Row) { queueSave({ ...workspace, [section]: value }); }
  function updateCreative(value: Row) { update("creative", value); }
  function updateConcept(patch: Row) { const next = concepts.length ? concepts.map(row => row.id === concept.id ? { ...row, ...patch } : row) : [{ ...concept, ...patch }]; updateCreative({ ...creative, concepts: next, selectedConceptId: concept.id }); }
  function updateScenes(value: Row[]) { updateConcept({ scenes: value.map((scene, index) => ({ ...scene, number: index + 1 })) }); }
  function rowsWithResource(key: string, resource: Row) {
    const rows: Row[] = Array.isArray(people[key]) ? [...people[key]] : [];
    const existing = rows.findIndex(row => String(row.name || "").toLowerCase() === String(resource.name || "").toLowerCase());
    if (existing >= 0) rows[existing] = { ...rows[existing], ...resource, id: rows[existing].id, archived: false };
    else rows.push(resource);
    return rows;
  }
  function sceneWithResourceIds(scene: Row, patch: Row, resource?: { key: string; row: Row }) {
    const next = { ...scene, ...patch };
    const rows = (key: string): Row[] => resource?.key === key ? rowsWithResource(key, resource.row) : (Array.isArray(people[key]) ? people[key] : []);
    const ids = (key: string, names: string[]) => names.map(name => rows(key).find(row => String(row.name || "").toLowerCase() === String(name).toLowerCase())?.id).filter(Boolean);
    if (Array.isArray(next.characters)) next.characterIds = ids("actors", next.characters);
    if ("location" in patch) next.locationId = next.location ? rows("locations").find(row => String(row.name || "").toLowerCase() === String(next.location).toLowerCase())?.id || next.locationId || "" : "";
    if (Array.isArray(next.outfits) || next.outfit) next.outfitIds = ids("outfits", [...(next.outfits || []), ...(next.outfit && !(next.outfits || []).includes(next.outfit) ? [next.outfit] : [])]);
    if (Array.isArray(next.props) || next.props) next.propIds = ids("props", Array.isArray(next.props) ? next.props : [next.props]);
    return next;
  }
  function updateScene(sceneId: string, patch: Row, resource?: { key: string; row: Row }) {
    if (draftScene?.id === sceneId) { setDraftScene(current => current ? sceneWithResourceIds(current, patch, resource) : current); if (resource) updatePeople(resource.key, rowsWithResource(resource.key, resource.row)); return; }
    const nextScenes = scenes.map(scene => scene.id === sceneId ? sceneWithResourceIds(scene, patch, resource) : scene).map((scene, index) => ({ ...scene, number: index + 1 }));
    const nextConcepts = concepts.length ? concepts.map(row => row.id === concept.id ? { ...row, scenes: nextScenes } : row) : [{ ...concept, scenes: nextScenes }];
    const nextPeople = resource ? { ...people, [resource.key]: rowsWithResource(resource.key, resource.row) } : people;
    queueSave({ ...workspace, creative: { ...creative, concepts: nextConcepts, selectedConceptId: concept.id }, ...(resource ? { people: nextPeople } : {}) });
  }
  function updatePeople(key: string, rows: Row[]) {
    const previous: Row[] = Array.isArray(people[key]) ? people[key] : [];
    const renamed = previous.flatMap((oldRow: Row) => { const newRow = rows.find((row: Row) => row.id && row.id === oldRow.id); return newRow && oldRow.name && newRow.name && oldRow.name !== newRow.name ? [{ from: oldRow.name, to: newRow.name }] : []; });
    let nextCreative = creative;
    if (renamed.length) {
      const updateName = (value: any) => renamed.reduce((result, item) => result === item.from ? item.to : result, value);
      const updateSceneNames = (scene: Row) => ({ ...scene, ...(key === "actors" ? { characters: (scene.characters || []).map(updateName) } : {}), ...(key === "locations" ? { location: updateName(scene.location) } : {}), ...(key === "outfits" ? { outfit: updateName(scene.outfit), outfits: (scene.outfits || []).map(updateName) } : {}), ...(key === "props" ? { props: (Array.isArray(scene.props) ? scene.props : scene.props ? [scene.props] : []).map(updateName) } : {}) });
      if (Array.isArray(creative.concepts)) nextCreative = { ...creative, concepts: creative.concepts.map((row: Row) => ({ ...row, scenes: (row.scenes || []).map(updateSceneNames) })) };
      else if (Array.isArray(creative.scenes)) nextCreative = { ...creative, scenes: creative.scenes.map(updateSceneNames) };
    }
    queueSave({ ...workspace, people: { ...people, [key]: rows }, ...(nextCreative !== creative ? { creative: nextCreative } : {}) });
  }
  function updateProduction(patch: Row) { update("production", { ...production, ...patch }); }
  function updateRelease(patch: Row) { const next = { ...release, ...patch }; if (patch.publicationConfirmed === true) { next.publicationStatus = "Published"; next.publicationDate = next.publicationDate || new Date().toISOString().slice(0, 10); } if (patch.publicationConfirmed === false && next.publicationStatus === "Published") next.publicationStatus = "Not published"; update("release", next); }

  function saveItem(value: Row) {
    if (!itemModal) return;
    if (itemModal.type === "task") {
      const rows: Row[] = [...tasks];
      if (itemModal.index === null) rows.push({ ...value, id: makeId(), status: value.status || "To Do" });
      else { const taskIndex = rows.findIndex(row => row.id === itemModal.value.id); if (taskIndex >= 0) rows[taskIndex] = { ...rows[taskIndex], ...value }; }
      updateProduction({ tasks: rows });
    } else {
      const rows: Row[] = [...(Array.isArray(people[itemModal.type]) ? people[itemModal.type] : [])];
      const editingAssigned = itemModal.value.id === "assigned-videographer";
      const rowIndex = editingAssigned ? -1 : rows.findIndex(row => row.id === itemModal.value.id);
      const duplicate = rows.find(row => row.name && String(row.name).toLowerCase() === String(value.name).toLowerCase() && row.id !== itemModal.value.id);
      if (itemModal.index === null && duplicate) { setNotice(`${value.name} is already saved. Select that person or resource in the scene editor.`); return; }
      if (rowIndex >= 0) rows[rowIndex] = { ...rows[rowIndex], ...value };
      else rows.push({ ...value, id: makeId(), archived: false });
      updatePeople(itemModal.type, rows);
      if (itemModal.type === "actors" && String(value.role || "").toLowerCase().includes("videographer")) void fetch("/api/music-video-projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id, assigned_videographer: { name: value.name, email: value.email, portfolio: value.portfolio } }) }).then(() => setProject(current => current ? { ...current, assigned_videographer: { name: value.name, email: value.email, portfolio: value.portfolio } } : current));
    }
    setItemModal(null);
  }
  function updateShot(sceneId: string, index: number, patch: Row) { const scene = scenes.find((row: Row) => row.id === sceneId) || draftScene; if (!scene) return; const shots = [...(scene.shots || [])]; shots[index] = { ...shots[index], ...patch }; updateScene(sceneId, { shots }); }
  function moveShot(sceneId: string, index: number, delta: number) { const scene = scenes.find((row: Row) => row.id === sceneId) || draftScene; if (!scene) return; const shots = [...(scene.shots || [])], target = index + delta; if (target < 0 || target >= shots.length) return; [shots[index], shots[target]] = [shots[target], shots[index]]; updateScene(sceneId, { shots }); }
  function closeSceneEditor() {
    if (draftScene && (draftScene.title?.trim() || draftScene.description?.trim() || draftScene.referenceUrl || (draftScene.referenceImages || []).length || draftScene.location || (draftScene.characters || []).length || (draftScene.outfits || []).length || (draftScene.props || []).length || (draftScene.shots || []).length)) {
      if (!window.confirm("Discard this unsaved scene?")) return;
    }
    setDraftScene(null); setActiveScene(null);
  }
  function saveDraftScene() {
    if (!draftScene?.title?.trim()) { setNotice("Add a scene title before saving."); return; }
    updateScenes([...scenes, { ...draftScene, title: draftScene.title.trim() }]);
    setDraftScene(null); setActiveScene(null);
  }
  async function inviteVideographer(person: Row) {
    const email = String(person.email || "").trim();
    if (!email) { setNotice("Add an email address to invite this person."); return; }
    const response = await fetch("/api/music-video-invites", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ projectId: id, emails: [email] }) });
    const result = await response.json();
    if (!response.ok) { setNotice(result.error || "Unable to create invite."); return; }
    const invite = result.invites?.[0];
    if (invite) { setInvites(current => ({ ...current, [email.toLowerCase()]: invite })); setNotice(result.emailStatus === "sent" ? "Invite sent" : "Private invite link ready"); }
  }
  async function revokeInvite(email: string) {
    const key = email.toLowerCase(), invite = invites[key]; if (!invite) return;
    const response = await fetch("/api/music-video-invites", { method: "DELETE", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: invite.id }) });
    if (response.ok) { setInvites(current => { const next = { ...current }; delete next[key]; return next; }); setNotice("Invite revoked"); }
  }
  async function uploadReference(file: File, onDone: (url: string) => void) {
    if (!file.type.startsWith("image/")) { setNotice("Choose an image file."); return; }
    const reader = new FileReader();
    reader.onload = () => {
      const image = new Image();
      image.onload = () => {
        const scale = Math.min(1, 1000 / Math.max(image.width, image.height));
        const canvas = document.createElement("canvas"); canvas.width = Math.round(image.width * scale); canvas.height = Math.round(image.height * scale);
        const context = canvas.getContext("2d"); if (!context) return;
        context.drawImage(image, 0, 0, canvas.width, canvas.height);
        const url = canvas.toDataURL("image/jpeg", 0.72);
        if (url.length > 180_000) { setNotice("That image is too large. Try a smaller image."); return; }
        onDone(url);
      };
      image.src = String(reader.result || "");
    };
    reader.readAsDataURL(file);
  }

  if (!project) return embedded ? <p className="p-4 text-sm text-white/55">{notice}</p> : <main className="min-h-screen bg-[#09090c] p-8 text-white">{notice}</main>;
  const Root = embedded ? "section" : "main";
  return <Root className={`${embedded ? "rounded-2xl border border-white/[.08] bg-[#0b0b0f] p-3 sm:p-5" : "min-h-screen bg-[#09090c] p-4 text-white sm:p-8"} text-white`}>
    {!embedded && <Link href={`/admin?view=songs&song=${encodeURIComponent(project.songs?.slug || "")}`} className="mb-4 inline-block text-xs text-white/45 hover:text-white">← Song workspace</Link>}
    <header className="flex flex-wrap items-center gap-3 border-b border-white/[.08] pb-4">
      {!embedded && <img src={songCoverPath(project.songs?.slug || "", project.songs?.title || "")} alt="" className="h-14 w-14 rounded-xl border border-white/10 object-cover" />}
      <div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><Clapperboard size={18} strokeWidth={1.8} className="text-white/45"/>{!embedded && <h1 className="truncate text-lg font-bold">{project.songs?.title || "Music Video"}</h1>}<span className="rounded-full bg-white/[.06] px-2.5 py-1 text-[.62rem] font-semibold text-white/65">{workspace.videoType || "Official Music Video"}</span><span className="rounded-full border border-[#FD52AF]/30 px-2.5 py-1 text-[.62rem] font-semibold text-[#FD52AF]">{overall}</span></div><p className="mt-1 truncate text-xs text-white/45">{scenes.length} scenes <span className="px-1">·</span> Tasks {doneTasks}/{visibleTasks.length} <span className="px-1">·</span> Shoot {production.shootDate || "Not scheduled"}</p></div>
      <span className="text-[.65rem] text-white/40" aria-live="polite">{notice}</span>
    </header>
    <nav aria-label="Music video stages" className="my-4 grid grid-cols-3 rounded-xl bg-white/[.035] p-1">{stages.map(([key, label, subtitle, Icon, iconColor]) => <button key={key} type="button" onClick={() => setStage(key)} className={`flex min-h-[72px] flex-col items-center justify-center gap-1 rounded-lg border px-2 py-2 transition ${stage === key ? "border-[#FD52AF]/35 bg-[#FD52AF]/[.10] text-white" : "border-transparent text-white/55 hover:bg-white/[.04] hover:text-white"}`}><span className="flex items-center gap-1.5"><Icon size={23} strokeWidth={1.9} className={iconColor}/>{stageProgress[key] && <CheckCircle2 size={14} className="text-emerald-300"/>}</span><span className="text-xs font-semibold sm:text-sm">{label}</span><span className="text-[.62rem] text-white/40">{subtitle}</span></button>)}</nav>

    {stage === "creative" && <div className="space-y-4">
      <section className={`${panel} p-4 sm:p-5`}>
        <div className="flex flex-wrap items-start gap-4">
          <div className="min-w-0 flex-1">
            <h2 className="flex items-center gap-2 text-sm font-bold"><Lightbulb size={19} className="text-[#FD52AF]"/>The Vision</h2>
            <label className="mt-4 block text-[.68rem] font-semibold text-white/55">Concept</label>
            <textarea aria-label="Video concept" value={concept.synopsis || ""} onChange={event => updateConcept({ synopsis: event.target.value, story: event.target.value })} rows={2} placeholder="What's the story or idea behind this video?" className={`${field} mt-1 min-h-20 resize-y bg-black/35 leading-6`}/>
            <details className="mt-2 text-xs text-white/45"><summary className="w-fit cursor-pointer hover:text-white/70">Optional video title</summary><input aria-label="Optional video title" value={concept.title || ""} onChange={event => updateConcept({ title: event.target.value })} placeholder="Use the song title by default" className={`${field} mt-2`}/></details>
          </div>
        </div>
        <div className="mt-4 grid gap-4 border-t border-white/[.06] pt-4 sm:grid-cols-2">
          <ChipGroup title="Visual style" tip="How the video looks." values={["Cinematic", "Dreamy", "Surreal", "Retro", "Raw", "Minimal", "Futuristic", "Documentary", "Experimental", ...(concept.customStyles || [])]} selected={concept.styles || []} onToggle={value => updateConcept({ styles: (concept.styles || []).includes(value) ? concept.styles.filter((item: string) => item !== value) : [...(concept.styles || []), value] })} onCustom={value => updateConcept({ customStyles: [...(concept.customStyles || []), value], styles: [...(concept.styles || []), value] })}/>
          <ChipGroup title="Mood" tip="How the video should feel." values={["Emotional", "Playful", "Dark", "Romantic", "Energetic", "Hopeful", "Intimate", "Mysterious", "Melancholic", ...(concept.customMoods || [])]} selected={concept.moods || []} onToggle={value => updateConcept({ moods: (concept.moods || []).includes(value) ? concept.moods.filter((item: string) => item !== value) : [...(concept.moods || []), value] })} onCustom={value => updateConcept({ customMoods: [...(concept.customMoods || []), value], moods: [...(concept.moods || []), value] })}/>
        </div>
        <details className="mt-4 border-t border-white/[.06] pt-3" open={Boolean((concept.inspirationImages || []).length || (concept.inspirationLinks || []).length || (concept.colorPalette || []).length)}>
          <summary className="flex w-fit cursor-pointer items-center gap-2 text-xs font-semibold text-white/65"><Images size={16} className="text-white/45"/>Inspiration <span className="font-normal text-white/35">Optional</span></summary>
          <div className="mt-3 flex flex-wrap items-center gap-2">{(concept.inspirationImages || []).map((url: string, index: number) => <div key={`${index}-${url.slice(0, 16)}`} className="group relative h-16 w-20 overflow-hidden rounded-lg border border-white/10"><img src={url} alt="Inspiration reference" className="h-full w-full object-cover"/><button type="button" aria-label="Remove inspiration image" onClick={() => updateConcept({ inspirationImages: concept.inspirationImages.filter((_: string, i: number) => i !== index) })} className="absolute right-1 top-1 rounded bg-black/70 p-1 text-white opacity-0 group-hover:opacity-100 focus:opacity-100"><Trash2 size={13}/></button></div>)}
            <label className="flex h-16 cursor-pointer items-center gap-1.5 rounded-lg border border-dashed border-white/15 px-3 text-xs text-white/55 hover:border-[#FD52AF]/40"><ImagePlus size={15}/>Upload image<input type="file" accept="image/*" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void uploadReference(file, url => updateConcept({ inspirationImages: [...(concept.inspirationImages || []), url] })); }}/></label>
            <input aria-label="Inspiration image URL" placeholder="Paste image URL, press Enter" onKeyDown={event => { if (event.key === "Enter") { event.preventDefault(); const input = event.currentTarget; if (input.value.trim()) { updateConcept({ inspirationImages: [...(concept.inspirationImages || []), input.value.trim()] }); input.value = ""; } } }} className="w-52 rounded-lg border border-white/10 bg-black/25 px-3 py-2 text-xs text-white outline-none focus:border-[#FD52AF]/50"/>
          </div>
          <div className="mt-3 flex flex-wrap items-center gap-2">{(concept.inspirationLinks || []).map((url: string, index: number) => <span key={`${url}-${index}`} className="inline-flex max-w-56 items-center gap-1 rounded-full border border-white/10 py-1 pl-3 pr-1.5 text-xs text-[#ff9dcd]"><a href={url} target="_blank" rel="noreferrer" className="truncate">{url}</a><button type="button" aria-label="Remove inspiration video link" onClick={() => updateConcept({ inspirationLinks: concept.inspirationLinks.filter((_: string, i: number) => i !== index) })} className="rounded-full p-1 text-white/40 hover:text-white"><Trash2 size={12}/></button></span>)}<input aria-label="Inspiration video link" placeholder="Paste video link, press Enter" onKeyDown={event => { if (event.key === "Enter") { event.preventDefault(); const input = event.currentTarget; const value = input.value.trim(); if (value) { updateConcept({ inspirationLinks: [...(concept.inspirationLinks || []), value] }); input.value = ""; } } }} className="w-52 rounded-lg border border-white/10 bg-black/25 px-3 py-2 text-xs text-white outline-none focus:border-[#FD52AF]/50"/>
            {(concept.colorPalette || []).map((color: string, index: number) => <button key={`${color}-${index}`} type="button" title={`Remove ${color}`} onClick={() => updateConcept({ colorPalette: concept.colorPalette.filter((_: string, i: number) => i !== index) })} className="h-7 w-7 rounded-full border border-white/25" style={{ backgroundColor: color }} />)}<input type="color" aria-label="Add a palette color" title="Add a palette color" onChange={event => { const value = event.target.value; if (!(concept.colorPalette || []).includes(value)) updateConcept({ colorPalette: [...(concept.colorPalette || []), value].slice(0, 6) }); }} className="h-8 w-8 cursor-pointer rounded-md border-0 bg-transparent p-0"/>
          </div>
        </details>
      </section>
      <section aria-label="Storyboard" className={`${panel} overflow-hidden`}>
        <div className="flex items-center gap-3 px-4 py-3 sm:px-5"><div className="mr-auto"><h2 className="flex items-center gap-2 text-sm font-bold"><PanelsTopLeft size={18} className="text-white/45"/>Storyboard <span className="font-normal text-white/40">{scenes.length} scenes</span></h2><p className="text-[.68rem] text-white/40">Drag scenes to reorder. Select a card to edit.</p></div><div className="flex rounded-lg border border-white/10 p-0.5"><button type="button" aria-label="Grid view" onClick={() => setSceneView("grid")} className={`rounded-md p-1.5 ${sceneView === "grid" ? "bg-white/10 text-[#FD52AF]" : "text-white/40"}`}><LayoutGrid size={15}/></button><button type="button" aria-label="List view" onClick={() => setSceneView("list")} className={`rounded-md p-1.5 ${sceneView === "list" ? "bg-white/10 text-[#FD52AF]" : "text-white/40"}`}><List size={15}/></button></div><button type="button" onClick={() => { const scene = { id: makeId(), title: "", description: "", location: "", characters: [], outfit: "", props: "", shots: [], status: "planned" }; setDraftScene(scene); setActiveScene(scene.id); }} className="flex items-center gap-1.5 rounded-lg bg-[#FD52AF] px-3 py-2 text-xs font-bold text-black"><Plus size={15}/>Add Scene</button></div>
        {!scenes.length ? <div className="m-4 grid min-h-48 place-items-center rounded-xl border border-dashed border-white/15 bg-white/[.02] text-center"><span><PanelsTopLeft size={20} className="mx-auto text-white/35"/><b className="mt-3 block text-sm">No scenes yet</b><span className="mt-1 block text-xs text-white/40">Start building your story.</span><button type="button" onClick={() => { const scene = { id: makeId(), title: "", description: "", location: "", characters: [], shots: [], status: "planned" }; setDraftScene(scene); setActiveScene(scene.id); }} className="mt-3 rounded-lg bg-[#FD52AF] px-3 py-2 text-xs font-bold text-black">Add your first scene</button></span></div> : <div className={sceneView === "grid" ? "grid grid-cols-1 gap-3 p-3 pt-1 sm:grid-cols-2" : "space-y-2 p-3 pt-1"}>{scenes.map((scene, index) => { const cover = sceneCover(scene); return <article key={scene.id} draggable onDragStart={() => { dragScene.current = scene.id; }} onDragOver={event => { event.preventDefault(); setDragOverScene(scene.id); }} onDragLeave={() => setDragOverScene(null)} onDrop={() => { const from = scenes.findIndex(row => row.id === dragScene.current), to = index; if (from >= 0 && from !== to) { const next = [...scenes]; const [moved] = next.splice(from, 1); next.splice(to, 0, moved); updateScenes(next); } dragScene.current = null; setDragOverScene(null); }} className={`group relative overflow-hidden rounded-xl border bg-[#0b0b0f] transition ${dragOverScene === scene.id ? "border-[#FD52AF]/60 bg-[#FD52AF]/[.04]" : "border-white/[.08] hover:border-white/20"} ${sceneView === "list" ? "flex items-center" : ""}`}>
          <button type="button" onClick={() => setActiveScene(scene.id)} className={`block text-left ${sceneView === "list" ? "flex min-w-0 flex-1 items-center gap-3" : "w-full"}`}>
            {cover ? <div className={`relative aspect-video overflow-hidden bg-black/30 ${sceneView === "list" ? "h-16 w-28 shrink-0" : "w-full"}`}><img src={cover} alt="" className="h-full w-full object-cover"/><span className="absolute left-2 top-2 rounded-md bg-black/70 px-2 py-1 text-[.62rem] font-semibold">SCENE {String(index + 1).padStart(2, "0")}</span></div> : <div className={`flex items-center gap-2 border-b border-white/[.05] px-3 py-2 text-xs text-white/40 ${sceneView === "list" ? "h-16 w-28 shrink-0 flex-col justify-center" : "min-h-12"}`}><ImagePlus size={15}/><span>No reference image</span></div>}
            <div className="min-w-0 p-3"><h3 className="flex items-center gap-2 truncate text-sm font-bold"><GripVertical size={14} className="shrink-0 text-white/25"/>{scene.title || `Scene ${String(index + 1).padStart(2, "0")}`}</h3><p className="mt-1 line-clamp-2 text-xs text-white/45">{scene.description || "Add a scene description"}</p><div className="mt-2 flex flex-wrap items-center gap-2 text-[.65rem] text-white/40">{scene.location && <span className="flex items-center gap-1"><MapPin size={12}/>{scene.location}</span>}<span className="rounded-full bg-white/[.06] px-2 py-1 capitalize">{scene.status || "planned"}</span></div></div>
          </button>
          {!cover && <label onClick={event => event.stopPropagation()} className="absolute right-3 top-2 flex cursor-pointer items-center gap-1 rounded-md border border-white/10 bg-[#17171c] px-2 py-1 text-[.62rem] text-[#ffadd6] hover:border-[#FD52AF]/50"><ImagePlus size={13}/>Add image<input type="file" accept="image/*" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void uploadReference(file, url => { const refs = [...sceneReferences(scene), { id: makeId(), url }]; updateScene(scene.id, { referenceImages: refs, coverReferenceId: refs[refs.length - 1].id, referenceUrl: url }); }); }}/></label>}
          <button type="button" aria-label={`Scene ${index + 1} actions`} onClick={() => setMenuScene(menuScene === scene.id ? null : scene.id)} className="absolute right-2 bottom-2 rounded-lg bg-black/65 p-2 text-white/70 opacity-0 transition group-hover:opacity-100 focus:opacity-100"><Ellipsis size={16}/></button>{menuScene === scene.id && <div className="absolute right-2 top-10 z-10 w-44 rounded-lg border border-white/10 bg-[#17171c] p-1 shadow-xl"><label className="flex cursor-pointer items-center gap-2 rounded px-2 py-2 text-xs text-white/70 hover:bg-white/[.06]"><ImagePlus size={14}/>Add / replace cover<input type="file" accept="image/*" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void uploadReference(file, url => { const refs = [...sceneReferences(scene), { id: makeId(), url }]; updateScene(scene.id, { referenceImages: refs, coverReferenceId: refs[refs.length - 1].id, referenceUrl: url }); }); }}/></label><button type="button" onClick={() => { const clone = { ...scene, id: makeId(), title: `${scene.title || "Scene"} copy`, shots: (scene.shots || []).map((shot: Row) => ({ ...shot, id: makeId() })) }; updateScenes([...scenes.slice(0, index + 1), clone, ...scenes.slice(index + 1)]); setMenuScene(null); }} className="block w-full rounded px-2 py-1.5 text-left text-xs hover:bg-white/[.06]">Duplicate</button><button type="button" onClick={() => { if (window.confirm("Delete this scene?")) updateScenes(scenes.filter(row => row.id !== scene.id)); setMenuScene(null); }} className="block w-full rounded px-2 py-1.5 text-left text-xs text-rose-300 hover:bg-white/[.06]">Delete</button></div>}</article>; })}</div>}
      </section>
    </div>}

    {stage === "production" && <div className="space-y-4">
      <section className={`${panel} grid gap-4 p-4 sm:grid-cols-[1fr_1.2fr] sm:p-5`}><div><h2 className="flex items-center gap-2 text-sm font-bold"><CalendarDays size={18} className="text-white/45"/>Shoot overview</h2><div className="mt-3 grid gap-2 sm:grid-cols-2"><label className="text-[.68rem] text-white/45">Shoot date<input type="date" value={production.shootDate || ""} onChange={event => updateProduction({ shootDate: event.target.value })} className={`${field} mt-1`}/></label><label className="text-[.68rem] text-white/45">Budget <span className="text-white/25">· optional</span><input type="text" value={production.budget || ""} onChange={event => updateProduction({ budget: event.target.value })} placeholder="$" className={`${field} mt-1`}/></label></div><textarea value={production.notes || ""} onChange={event => updateProduction({ notes: event.target.value })} rows={2} placeholder="Shoot notes (optional)" className={`${field} mt-2 resize-y`}/></div><div><div className="flex items-center"><h2 className="mr-auto flex items-center gap-2 text-sm font-bold"><ListChecks size={17} className="text-white/45"/>To-do list</h2><span className="text-xs text-white/40">{doneTasks}/{visibleTasks.length} complete</span><button type="button" onClick={() => setItemModal({ type: "task", index: null, value: { name: "", status: "To Do", dueDate: "" } })} className="ml-3 flex items-center gap-1 rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-[#ff9dcd]"><Plus size={14}/>Task</button></div><div className="mt-2 divide-y divide-white/[.06]">{sortedTasks.map(({ task, index }) => <div key={task.id || index} className="flex items-center gap-2 py-2"><input type="checkbox" aria-label={`Mark ${task.name} complete`} checked={task.status === "Done"} onChange={event => updateProduction({ tasks: tasks.map((row, i) => i === index ? { ...row, status: event.target.checked ? "Done" : "To Do" } : row) })} className="accent-[#FD52AF]"/><button type="button" onClick={() => setItemModal({ type: "task", index, value: task })} className="min-w-0 flex-1 truncate text-left text-xs">{task.name}</button>{task.dueDate && <span className="text-[.62rem] text-white/35">{task.dueDate}</span>}{task.assignee && <span className="max-w-24 truncate text-[.62rem] text-white/35">{task.assignee}</span>}<button type="button" aria-label="Delete task" onClick={() => { if (window.confirm("Delete this task?")) updateProduction({ tasks: tasks.filter((_, i) => i !== index) }); }} className="rounded-md p-1.5 text-white/35 hover:text-rose-300"><Trash2 size={14}/></button></div>)}{!visibleTasks.length && <p className="py-4 text-xs text-white/35">Nothing on your checklist yet.</p>}</div></div></section>
      <section className={`${panel} p-4 sm:p-5`}><div className="mb-2 flex items-center"><h2 className="mr-auto flex items-center gap-2 text-sm font-bold"><Users size={18} className="text-white/45"/>Cast &amp; crew</h2><button type="button" onClick={() => setItemModal({ type: "actors", index: null, value: { name: "", role: "", status: "Planned", email: "", phone: "", agreement: "" } })} className="rounded-lg border border-white/10 px-2.5 py-1.5 text-xs text-[#ff9dcd]"><Plus size={14} className="inline"/> Person</button></div><CompactList rows={cast} empty="Add only the people this video needs." onAdd={() => setItemModal({ type: "actors", index: null, value: { name: "", role: "", status: "Planned" } })} onEdit={index => setItemModal({ type: "actors", index, value: cast[index] })} onRemove={index => { const person = cast[index]; if (person?.id === "assigned-videographer") { void fetch("/api/music-video-projects", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ id, assigned_videographer: {} }) }); setProject(current => current ? { ...current, assigned_videographer: {} } : current); } else updatePeople("actors", castStored.map((row: Row) => row.id === person?.id ? { ...row, archived: true } : row)); }} onInvite={person => inviteVideographer(person)} inviteFor={person => invites[String(person.email || "").toLowerCase()]} onRevoke={person => revokeInvite(String(person.email || ""))} label="People"/></section>
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        <section className={`${panel} p-4`}><div className="mb-2 flex items-center"><h2 className="mr-auto flex items-center gap-2 text-sm font-bold"><MapPin size={18} className="text-white/45"/>Locations</h2><button type="button" onClick={() => setItemModal({ type: "locations", index: null, value: { name: "", address: "", notes: "", status: "Idea" } })} className="flex items-center gap-1 text-xs text-[#ff9dcd]"><Plus size={14}/>Add</button></div><CompactList rows={locations} empty="Save places where your story happens." onAdd={() => setItemModal({ type: "locations", index: null, value: { name: "", status: "Idea" } })} onEdit={index => setItemModal({ type: "locations", index, value: locations[index] })} onRemove={index => { const location = locations[index]; updatePeople("locations", (people.locations || []).map((row: Row) => row.id === location?.id ? { ...row, archived: true } : row)); }} label="Locations"/></section>
        <ResourceItems title="Wardrobe" icon={Shirt} rows={outfits} empty="Plan the looks for your scenes." scenes={scenes} type="outfits" onAdd={() => setItemModal({ type: "outfits", index: null, value: { name: "", status: "Needed", kind: "Outfit" } })} onEdit={(index, row) => setItemModal({ type: "outfits", index, value: row })} onArchive={row => updatePeople("outfits", (people.outfits || []).map((item: Row) => item.id === row.id ? { ...item, archived: true } : item))}/>
        <ResourceItems title="Props" icon={Package} rows={props} empty="Add props only when the video needs them." scenes={scenes} type="props" onAdd={() => setItemModal({ type: "props", index: null, value: { name: "", status: "Needed", kind: "Prop" } })} onEdit={(index, row) => setItemModal({ type: "props", index, value: row })} onArchive={row => updatePeople("props", (people.props || []).map((item: Row) => item.id === row.id ? { ...item, archived: true } : item))}/>
      </div>
    </div>}

    {stage === "release" && <section className={`${panel} max-w-3xl p-4 sm:p-6`}><div className="flex flex-wrap items-center gap-3"><div className="mr-auto"><h2 className="flex items-center gap-2 text-base font-bold"><Film size={19} className="text-white/45"/>Finish &amp; publish</h2><p className="mt-1 text-xs text-white/45">Video release is separate from the song’s audio release.</p></div><span className={`rounded-full px-3 py-1 text-xs font-semibold ${releasePublished ? "bg-emerald-300/10 text-emerald-200" : "bg-white/[.06] text-white/50"}`}>{releasePublished ? "Published" : "Not published"}</span></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="text-xs text-white/50">Editing status<select value={editingStatus} onChange={event => updateRelease({ editingStatus: event.target.value })} className={`${field} mt-1`}><option>Not Started</option><option>Editing</option><option>In Review</option><option>Final</option></select></label><label className="text-xs text-white/50">Target video release date<input type="date" value={release.releaseDate || ""} onChange={event => updateRelease({ releaseDate: event.target.value })} className={`${field} mt-1`}/></label>{releasePublished && <label className="text-xs text-white/50">Publication date<input type="date" value={release.publicationDate || ""} onChange={event => updateRelease({ publicationDate: event.target.value })} className={`${field} mt-1`}/></label>}<label className="text-xs text-white/50 sm:col-span-2">Published video URL<input type="url" value={release.videoUrl || ""} onChange={event => updateRelease({ videoUrl: event.target.value })} placeholder="https://…" className={`${field} mt-1`}/>{releasePublished && release.videoUrl && <a href={release.videoUrl} target="_blank" rel="noreferrer" className="mt-2 inline-flex items-center gap-1 text-xs text-[#ff9dcd] underline">Open published video <ExternalLinkIcon/></a>}{release.publicationDate && <span className="ml-3 text-xs text-white/40">Published {release.publicationDate}</span>}</label></div><div className="mt-5 flex flex-wrap items-center gap-3 border-t border-white/[.07] pt-4"><label className="mr-auto flex cursor-pointer items-center gap-2 text-sm"><input type="checkbox" checked={release.finalApproved === "yes"} onChange={event => updateRelease({ finalApproved: event.target.checked ? "yes" : "no" })} className="h-4 w-4 accent-[#FD52AF]"/>Final video approved</label></div><div className="mt-5 flex flex-wrap items-center gap-3 border-t border-white/[.07] pt-4"><p className="mr-auto text-xs text-white/40">Saving a URL alone will not change publication status.</p><button type="button" onClick={() => updateRelease({ publicationConfirmed: !releasePublished, publicationStatus: releasePublished ? "Not published" : "Published" })} className={`rounded-lg px-4 py-2.5 text-sm font-semibold ${releasePublished ? "border border-white/15 bg-white/[.04] text-white/75" : "bg-[#FD52AF] text-black"}`}>{releasePublished ? "Mark as Not Published" : "Mark as Published"}</button></div></section>}

    {active && <div className="fixed inset-0 z-[150] flex items-end justify-center bg-black/75 p-0 backdrop-blur-sm sm:items-center sm:p-4" onMouseDown={event => { if (event.target === event.currentTarget) closeSceneEditor(); }}><section role="dialog" aria-modal="true" aria-label={`Scene details: ${active.title}`} className="h-[100dvh] w-full overflow-y-auto border border-white/10 bg-[#111116] p-4 shadow-2xl sm:h-auto sm:max-h-[92vh] sm:max-w-5xl sm:rounded-2xl sm:p-6"><div className="flex items-center gap-3"><div className="mr-auto"><p className="text-[.62rem] font-bold uppercase tracking-[.14em] text-[#FD52AF]">Scene {scenes.findIndex(row => row.id === active.id) + 1}</p><h2 className="mt-1 text-lg font-bold">Scene {String(scenes.findIndex(row => row.id === active.id) + 1).padStart(2, "0")} — {active.title || "New scene"}</h2><p className="mt-1 flex items-center gap-1 text-xs capitalize text-white/45"><Clock3 size={13}/>{active.status || "planned"}</p></div><button type="button" onClick={closeSceneEditor} aria-label="Close scene" className="rounded-lg p-2 text-white/55 hover:bg-white/[.06]"><X size={17}/></button></div><div className="mt-4 grid gap-4 sm:grid-cols-[1fr_1.1fr]"><div><h3 className="mb-2 flex items-center gap-2 text-xs font-semibold text-white/60"><Images size={15}/>References</h3><div className="grid grid-cols-2 gap-2">{sceneReferences(active).map((reference: Row) => <div key={reference.id} className="group relative overflow-hidden rounded-lg border border-white/10"><img src={reference.url} alt="Scene reference" className="aspect-[4/3] w-full object-cover"/><div className="absolute inset-x-1 bottom-1 flex items-center justify-between"><button type="button" aria-pressed={reference.id === active.coverReferenceId || (!active.coverReferenceId && reference.id === sceneReferences(active)[0]?.id)} onClick={() => updateScene(active.id, { coverReferenceId: reference.id, referenceUrl: reference.url })} className="rounded bg-black/75 px-2 py-1 text-[.6rem] text-white">{reference.id === active.coverReferenceId || (!active.coverReferenceId && reference.id === sceneReferences(active)[0]?.id) ? "Cover" : "Set cover"}</button><button type="button" aria-label="Remove reference image" onClick={() => { const next = sceneReferences(active).filter(item => item.id !== reference.id); const cover = next.find(item => item.id === active.coverReferenceId) || next[0]; updateScene(active.id, { referenceImages: next, coverReferenceId: cover?.id || "", referenceUrl: cover?.url || "" }); }} className="rounded bg-black/75 p-1.5 text-white"><Trash2 size={13}/></button></div></div>)}<label className="flex aspect-[4/3] cursor-pointer flex-col items-center justify-center gap-1 rounded-lg border border-dashed border-white/15 text-xs text-white/45 hover:border-[#FD52AF]/40 hover:text-white/75"><ImagePlus size={18}/>Upload<input type="file" accept="image/*" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void uploadReference(file, url => { const refs = [...sceneReferences(active), { id: makeId(), url }]; const cover = active.coverReferenceId || refs[0].id; updateScene(active.id, { referenceImages: refs, coverReferenceId: cover, referenceUrl: refs.find(item => item.id === cover)?.url || url }); }); }}/></label></div><input aria-label="Paste image URL" onKeyDown={event => { if (event.key === "Enter") { event.preventDefault(); const input = event.currentTarget; const url = input.value.trim(); if (url) { const refs = [...sceneReferences(active), { id: makeId(), url }]; const cover = active.coverReferenceId || refs[0].id; updateScene(active.id, { referenceImages: refs, coverReferenceId: cover, referenceUrl: refs.find(item => item.id === cover)?.url || url }); input.value = ""; } } }} placeholder="Paste image URL and press Enter" className={`${field} mt-2 text-xs`}/></div><div className="space-y-3"><input aria-label="Scene title" value={active.title || ""} onChange={event => updateScene(active.id, { title: event.target.value })} placeholder="Scene title" className={`${field} text-base font-semibold`}/><textarea aria-label="Scene description" value={active.description || ""} onChange={event => updateScene(active.id, { description: event.target.value })} rows={5} placeholder="What happens in this scene?" className={`${field} min-h-32 resize-y`}/><label className="block text-xs font-medium text-white/55">Status<select value={active.status || "planned"} onChange={event => updateScene(active.id, { status: event.target.value })} className={`${field} mt-1 bg-[#17171c]`}><option value="planned">Planned</option><option value="ready">Ready</option><option value="filmed">Filmed</option></select></label>
          <details className="rounded-xl border border-white/[.07] px-3 py-2.5" open={Boolean(active.location || (active.characters || []).length || (active.outfits || []).length || active.outfit || (active.props || []).length)}><summary className="cursor-pointer text-xs font-semibold text-white/65">Production details</summary><div className="mt-3 space-y-3"><label className="block text-xs text-white/55">Location<input list="music-video-locations" value={active.location || ""} onChange={event => updateScene(active.id, { location: event.target.value })} onBlur={event => { const name = event.currentTarget.value.trim(); if (name && !locations.some((location: Row) => String(location.name).toLowerCase() === name.toLowerCase())) { const existing = (people.locations || []).find((location: Row) => String(location.name).toLowerCase() === name.toLowerCase()); const record = existing ? { ...existing, archived: false } : { id: makeId(), name, status: "Idea" }; updateScene(active.id, { location: name }, { key: "locations", row: record }); } }} placeholder="Search or add a location" className={`${field} mt-1`}/><datalist id="music-video-locations">{savedLocationNames.map(name => <option key={name} value={name}/>)}</datalist></label>
            <Selector label="Cast" options={savedCastNames} values={active.characters || []} onChange={(values, resource) => updateScene(active.id, { characters: values }, resource ? { key: "actors", row: resource } : undefined)} onCreate={name => castStored.some(person => String(person.name).toLowerCase() === name.toLowerCase()) ? undefined : { id: makeId(), name, role: "Actor", status: "Planned" }}/>
            <Selector label="Wardrobe" options={outfits.map((row: Row) => row.name).filter(Boolean)} values={active.outfits || (active.outfit ? [active.outfit] : [])} onChange={(values, resource) => updateScene(active.id, { outfits: values, outfit: values[0] || "" }, resource ? { key: "outfits", row: resource } : undefined)} onCreate={name => { const existing = (people.outfits || []).find((row: Row) => String(row.name).toLowerCase() === name.toLowerCase()); return { ...existing, id: existing?.id || makeId(), name, kind: "Outfit", status: existing?.status || "Needed", archived: false }; }}/>
            <Selector label="Props" options={props.map((row: Row) => row.name).filter(Boolean)} values={Array.isArray(active.props) ? active.props : active.props ? [active.props] : []} onChange={(values, resource) => updateScene(active.id, { props: values }, resource ? { key: "props", row: resource } : undefined)} onCreate={name => { const existing = (people.props || []).find((row: Row) => String(row.name).toLowerCase() === name.toLowerCase()); return { ...existing, id: existing?.id || makeId(), name, kind: "Prop", status: existing?.status || "Needed", archived: false }; }}/>
          </div></details>
        </div></div>{!(active.shots || []).length && <button type="button" onClick={() => updateScene(active.id, { shots: [{ id: makeId(), text: "", done: false }] })} className="mt-4 flex items-center gap-2 border-t border-white/[.07] pt-3 text-xs font-semibold text-[#ff9dcd]"><Camera size={14}/>Add Shot <span className="font-normal text-white/35">Optional</span></button>}{(active.shots || []).length > 0 && <details className="mt-4 border-t border-white/[.07] pt-3" open><summary className="flex cursor-pointer list-none items-center gap-2 text-xs font-semibold text-white/65"><Camera size={14}/>Shot list <span className="font-normal text-white/35">{(active.shots || []).length}</span></summary><div className="mt-2"><div className="flex items-center"><h3 className="mr-auto text-xs font-bold">Shots</h3><button type="button" onClick={() => updateScene(active.id, { shots: [...(active.shots || []), { id: makeId(), text: "", done: false }] })} className="flex items-center gap-1 text-xs text-[#ff9dcd]"><Plus size={14}/>Add Shot</button></div>{(active.shots || []).map((shot: Row, index: number) => <div key={shot.id || index} className="mt-2 grid grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-2 rounded-lg border border-white/[.06] p-2"><input aria-label="Shot complete" type="checkbox" checked={!!shot.done} onChange={event => updateShot(active.id, index, { done: event.target.checked })} className="accent-[#FD52AF]"/><div className="min-w-0"><input value={shot.text || ""} onChange={event => updateShot(active.id, index, { text: event.target.value })} placeholder="What do we see?" className={`${field} text-xs`}/><div className="mt-1 flex flex-wrap items-center gap-2"><select aria-label="Optional shot type" value={shot.type || ""} onChange={event => updateShot(active.id, index, { type: event.target.value })} className="rounded-md border border-white/10 bg-[#17171c] px-2 py-1 text-[.65rem] text-white/60"><option value="">Shot type (optional)</option>{["Wide", "Medium", "Close-up", "Detail", "Moving"].map(type => <option key={type}>{type}</option>)}</select>{shot.referenceUrl && <img src={shot.referenceUrl} alt="Shot reference" className="h-8 w-12 rounded object-cover"/>}<label className="flex cursor-pointer items-center gap-1 text-[.65rem] text-white/45 hover:text-[#ff9dcd]"><ImagePlus size={13}/>Image<input type="file" accept="image/*" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) void uploadReference(file, url => updateShot(active.id, index, { referenceUrl: url })); }}/></label></div></div><div className="flex items-center"><button type="button" aria-label="Move shot up" onClick={() => moveShot(active.id, index, -1)} disabled={!index} className="rounded p-1 text-white/40 hover:text-white disabled:opacity-20"><ArrowUp size={14}/></button><button type="button" aria-label="Move shot down" onClick={() => moveShot(active.id, index, 1)} disabled={index === active.shots.length - 1} className="rounded p-1 text-white/40 hover:text-white disabled:opacity-20"><ArrowDown size={14}/></button><button type="button" aria-label="Duplicate shot" onClick={() => updateScene(active.id, { shots: [...active.shots.slice(0, index + 1), { ...shot, id: makeId() }, ...active.shots.slice(index + 1)] })} className="rounded p-1 text-white/40 hover:text-white"><Copy size={14}/></button><button type="button" aria-label="Delete shot" onClick={() => updateScene(active.id, { shots: active.shots.filter((_: Row, i: number) => i !== index) })} className="rounded p-1 text-white/40 hover:text-rose-300"><Trash2 size={14}/></button></div></div>)}</div></details>}<div className="mt-5 flex justify-end gap-2 border-t border-white/[.08] pt-4"><button type="button" onClick={closeSceneEditor} className="rounded-lg border border-white/10 px-4 py-2 text-xs text-white/70">{draftScene ? "Cancel" : "Close"}</button>{draftScene && <button type="button" onClick={saveDraftScene} className="rounded-lg bg-[#FD52AF] px-4 py-2 text-xs font-bold text-black">Save Scene</button>}</div></section></div>}

    {itemModal && <ItemEditor peopleOptions={savedCastNames} modal={itemModal} onClose={() => setItemModal(null)} onUpload={file => uploadReference(file, url => setItemModal(current => current ? { ...current, value: { ...current.value, imageUrl: url } } : current))} onSave={saveItem}/>
    }
  </Root>;
}

function Thumb({ src, name }: { src?: string; name?: string }) { return src ? <img src={src} alt="" className="h-9 w-9 rounded-lg object-cover"/> : <div className="grid h-9 w-9 place-items-center rounded-lg bg-white/[.06] text-[.6rem] text-white/45">{initials(name || "")}</div>; }
function ResourceItems({ title, icon: Icon, rows, empty, scenes, type, onAdd, onEdit, onArchive }: { title: string; icon: typeof Shirt; rows: Row[]; empty: string; scenes: Row[]; type: "outfits" | "props"; onAdd: () => void; onEdit: (index: number, row: Row) => void; onArchive: (row: Row) => void }) {
  const visible = rows.map((row, index) => ({ row, index })).filter(({ row }) => String(row.name || "").trim());
  function assignedTo(name: string) { return scenes.map((scene, index) => { const names = type === "outfits" ? [...(scene.outfits || []), ...(scene.outfit ? [scene.outfit] : [])] : Array.isArray(scene.props) ? scene.props : scene.props ? [scene.props] : []; return names.includes(name) ? `Scene ${String(index + 1).padStart(2, "0")}` : ""; }).filter(Boolean); }
  return <section className="rounded-2xl border border-white/[.08] bg-[#111116] p-4"><div className="mb-2 flex items-center"><h2 className="mr-auto flex items-center gap-2 text-sm font-bold"><Icon size={18} className="text-white/45"/>{title}</h2><button type="button" onClick={onAdd} className="flex items-center gap-1 text-xs text-[#ff9dcd]"><Plus size={14}/>Add</button></div><div className="divide-y divide-white/[.05]">{visible.map(({ row, index }) => <div key={row.id || index} className="flex items-center gap-2 py-2"><Thumb src={row.imageUrl || row.reference} name={row.name}/><button type="button" onClick={() => onEdit(index, row)} className="min-w-0 flex-1 text-left"><b className="block truncate text-xs">{row.name}</b><span className="block truncate text-[.65rem] text-white/40">{assignedTo(row.name).join(" · ") || (row.kind || (type === "props" ? "Prop" : "Outfit"))}</span></button><span className="text-[.65rem] text-white/50">{row.status || "Needed"}</span><button type="button" aria-label={`Archive ${row.name}`} onClick={() => onArchive(row)} className="rounded-md p-1.5 text-white/35 hover:text-rose-300"><Trash2 size={14}/></button></div>)}{!visible.length && <div className="flex items-center justify-between py-3"><p className="text-xs text-white/40">{empty}</p><button type="button" onClick={onAdd} className="text-xs text-[#ff9dcd]">Add item</button></div>}</div></section>;
}
function CompactList({ rows, empty, onAdd, onEdit, onRemove, onInvite, inviteFor, onRevoke, label }: { rows: Row[]; empty: string; onAdd: () => void; onEdit: (index: number) => void; onRemove: (index: number) => void; onInvite?: (row: Row) => void; inviteFor?: (row: Row) => { id: string; email?: string; link?: string } | undefined; onRevoke?: (row: Row) => void; label: string }) {
  const visible = rows.map((row, index) => ({ row, index })).filter(({ row }) => String(row.name || "").trim());
  return <div className="divide-y divide-white/[.05]">{visible.map(({ row, index }) => <div key={row.id || index} className="flex items-center gap-3 py-2.5"><Thumb src={row.imageUrl || row.reference} name={row.name}/><button type="button" onClick={() => onEdit(index)} className="min-w-0 flex-1 text-left"><b className="block truncate text-sm font-medium">{row.name}</b><span className="block truncate text-xs text-white/40">{row.role || row.address || row.email || row.notes || row.kind || ""}</span></button><span className="rounded-full bg-white/[.05] px-2 py-1 text-[.65rem] text-white/55">{row.status || "Planned"}</span>{onInvite && String(row.role || "").toLowerCase().includes("videographer") && <>{inviteFor?.(row) ? <><span className="max-w-28 truncate text-xs text-[#ff9dcd]">{inviteFor(row)?.link ? <a href={inviteFor(row)?.link} className="underline">Private invite</a> : "Invite active"}</span><button type="button" onClick={() => onRevoke?.(row)} className="text-xs text-rose-300">Revoke</button></> : <button type="button" onClick={() => onInvite(row)} className="rounded-md border border-[#FD52AF]/25 px-2 py-1 text-xs text-[#ff9dcd]">Invite</button>}</>}<button type="button" onClick={() => onRemove(index)} aria-label={`Remove ${row.name}`} className="rounded-md p-2 text-white/35 hover:bg-rose-400/10 hover:text-rose-300"><Trash2 size={15}/></button></div>)}{!visible.length && <div className="flex items-center justify-between py-3"><p className="text-xs text-white/40">{empty}</p><button type="button" onClick={onAdd} className="flex items-center gap-1 text-xs font-semibold text-[#ff9dcd]"><Plus size={14}/>Add {label.replace(/s$/, "")}</button></div>}</div>;
}
function Selector({ label, options, values, onChange, onCreate }: { label: string; options: string[]; values: string[]; onChange: (values: string[], created?: Row) => void; onCreate?: (value: string) => Row | undefined }) {
  const [query, setQuery] = useState("");
  const listId = `mv-${label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  function addValue() {
    const name = query.trim();
    if (!name || values.some(value => value.toLowerCase() === name.toLowerCase())) return;
    const existing = options.find(value => value.toLowerCase() === name.toLowerCase());
    const created = existing ? undefined : onCreate?.(name);
    if (!existing && onCreate && !created) return;
    onChange([...values, existing || name], created); setQuery("");
  }
  return <div className="text-xs text-white/55"><label htmlFor={`${listId}-input`} className="font-medium">{label}</label><div className="mt-1 flex gap-2"><input id={`${listId}-input`} list={listId} value={query} onChange={event => setQuery(event.target.value)} onKeyDown={event => { if (event.key === "Enter") { event.preventDefault(); addValue(); } }} placeholder={`Search or add ${label.toLowerCase()}`} className={`${field} min-w-0 py-2 text-xs`}/><datalist id={listId}>{options.filter(value => !values.includes(value)).map(value => <option key={value} value={value}/>)}</datalist><button type="button" onClick={addValue} aria-label={`Add ${label}`} className="rounded-lg border border-white/10 px-3 text-[#ff9dcd] hover:border-[#FD52AF]/40"><Plus size={15}/></button></div><div className="mt-2 flex flex-wrap gap-1.5">{values.map(value => <span key={value} className="inline-flex items-center gap-1 rounded-full border border-white/10 bg-white/[.04] py-1 pl-2.5 pr-1 text-xs text-white/70">{value}<button type="button" aria-label={`Remove ${value} from scene`} onClick={() => onChange(values.filter(item => item !== value))} className="rounded-full p-1 text-white/40 hover:text-white"><X size={12} aria-hidden="true"/></button></span>)}</div></div>;
}
function ItemEditor({ modal, onClose, onSave, onUpload, peopleOptions }: { peopleOptions: string[]; modal: { type: string; index: number | null; value: Row }; onClose: () => void; onSave: (value: Row) => void; onUpload: (file: File) => void }) { const [value, setValue] = useState<Row>(modal.value); useEffect(() => setValue(modal.value), [modal.value]); const titles: Record<string, string> = { actors: "Person", locations: "Location", outfits: "Outfit", props: "Prop", task: "Task" }; const status: Record<string, string[]> = { actors: ["Planned", "Contacted", "Confirmed", "Declined", "Considering", "Invited", "Completed"], locations: ["Idea", "Contacted", "Confirmed"], outfits: ["Needed", "Sourced", "Ready"], props: ["Needed", "Sourced", "Ready"], task: ["To Do", "In Progress", "Done"] }; const fields: Record<string, Array<[string, string]>> = { actors: [["name", "Name"], ["role", "Role"], ["email", "Email"], ["phone", "Phone"], ["agreement", "Agreement or notes"]], locations: [["name", "Location name"], ["address", "Address"], ["notes", "Notes"]], outfits: [["name", "Outfit"], ["notes", "Notes"]], props: [["name", "Prop"], ["notes", "Notes"]], task: [["name", "Task"], ["dueDate", "Due date"], ["assignee", "Assigned person (optional)"]] }; return <div className="fixed inset-0 z-[170] grid place-items-center bg-black/75 p-3" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><form onSubmit={event => { event.preventDefault(); onSave(value); }} className="max-h-[92dvh] w-full max-w-lg overflow-y-auto rounded-2xl border border-white/10 bg-[#15151b] p-5 shadow-2xl sm:p-6"><div className="flex items-center"><h2 className="mr-auto text-base font-bold">{modal.index === null ? `Add ${titles[modal.type]}` : `Edit ${titles[modal.type]}`}</h2><button type="button" onClick={onClose} aria-label="Close editor" className="rounded-lg p-2 text-white/45 hover:bg-white/[.06]"><X size={16}/></button></div><div className="mt-3 space-y-3">{fields[modal.type].map(([key, title]) => <label key={key} className="block text-[.68rem] text-white/45">{title}<input type={key === "dueDate" ? "date" : "text"} required={key === "name"} list={key === "role" ? "music-video-roles" : key === "assignee" ? "music-video-people" : undefined} value={value[key] || ""} onChange={event => setValue({ ...value, [key]: event.target.value })} className={`${field} mt-1`}/></label>)}{modal.type === "task" && <datalist id="music-video-people">{[...new Set(peopleOptions.filter(Boolean))].map(name => <option key={name} value={name}/>)}</datalist>}{modal.type === "actors" && <datalist id="music-video-roles">{["Actor", "Featured Talent", "Extra", "Director", "Videographer", "Director of Photography", "Editor", "Producer", "Assistant", "Makeup Artist", "Hair Stylist", "Wardrobe Stylist", "Other"].map(role => <option key={role} value={role}/>)}</datalist>}{modal.type !== "task" && <label className="block text-[.68rem] text-white/45">Status<select value={value.status || status[modal.type][0]} onChange={event => setValue({ ...value, status: event.target.value })} className={`${field} mt-1 bg-[#17171c]`}>{[...status[modal.type], ...(value.status && !status[modal.type].includes(value.status) ? [value.status] : [])].map(option => <option key={option}>{option}</option>)}</select></label>}{["outfits", "props", "locations"].includes(modal.type) && <><label className="block text-[.68rem] text-white/45">Image URL<input value={value.imageUrl || value.reference || ""} onChange={event => setValue({ ...value, imageUrl: event.target.value })} placeholder="https://…" className={`${field} mt-1`}/></label><label className="block text-[.68rem] text-white/45">Or upload an image<input type="file" accept="image/*" onChange={event => { const file = event.target.files?.[0]; if (file) onUpload(file); }} className="mt-1 block w-full text-xs text-white/60"/></label>{(value.imageUrl || value.reference) && <img src={value.imageUrl || value.reference} alt="Item preview" className="h-24 w-24 rounded-lg object-cover"/>}</>}</div><div className="mt-4 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-lg border border-white/10 px-3 py-2 text-xs">Cancel</button><button type="submit" className="rounded-lg bg-[#FD52AF] px-4 py-2 text-xs font-bold text-black">Save</button></div></form></div>; }
